import IconButton from "src/components/shared/Buttons/IconButton";
import { useMessagesContext, useSystemContext } from "src/contexts/hooks";
import clsx from "clsx";
import { SystemContextType } from "src/contexts/SystemContext";

import IconExpand from "src/assets/SvgIcons/IconExpand";
import IconCollapse from "src/assets/SvgIcons/IconCollapse";
import IconSidebar from "src/assets/SvgIcons/IconSideBar";
import GooeyTooltip from "src/components/shared/Tooltip";
import IconChevronDown from "src/assets/SvgIcons/IconChevronDown";
import IconPencilEdit from "src/assets/SvgIcons/PencilEdit";
import Button from "src/components/shared/Buttons/Button";
import BotAvatar from "src/components/shared/BotAvatar";
import IconClose from "src/assets/SvgIcons/IconClose";
import { ShareButton } from "./ShareDialog";
import { addInlineStyle } from "src/addStyles";
import style from "./header.scss?inline";

addInlineStyle(style);

const Header = () => {
  const { layoutController, config }: SystemContextType = useSystemContext();
  const {
    messages,
    handleNewConversation,
    currentConversation,
    isSending,
    isReceiving,
  } = useMessagesContext();
  const isEmpty = !messages?.size;
  const branding = config?.branding;
  const onClose = config?.onClose;
  const focusLabel = layoutController?.isFocusMode
    ? "Disable Focus"
    : "Enable Focus";

  return (
    <div className="gooey-chat-header bg-white b-btm-1 gp-8 d-flex justify-between align-center pos-sticky top-0 w-100 h-header">
      <div className="d-flex align-center">
        {/* Sidebar button */}
        {layoutController?.showSidebarButton && (
          <GooeyTooltip text="Open sidebar">
            <IconButton
              aria-label="Open sidebar"
              id="sidebar-toggle-icon-header"
              variant="text"
              className="cr-pointer"
              onClick={layoutController?.toggleSidebar}
            >
              <IconSidebar size={20} />
            </IconButton>
          </GooeyTooltip>
        )}
        <GooeyTooltip text="New Chat" disabled={isEmpty}>
          <Button onClick={handleNewConversation} disabled={isEmpty}>
            <div className="d-flex align-center">
              <BotAvatar
                size={24}
                src={branding?.photoUrl || "https://gooey.ai/favicon.ico"}
                className="gmr-8"
              />
              <p className="font_16_700 text-almostBlack">
                {branding?.title || "New Chat"}
              </p>
            </div>
          </Button>
        </GooeyTooltip>
      </div>

      <div>
        <div className="d-flex align-center">
          {/* Focus mode button */}
          {layoutController?.showFocusModeButton && (
            <GooeyTooltip text={focusLabel}>
              <IconButton
                aria-label={focusLabel}
                variant="text"
                className="gooey-focus-mode-button cr-pointer"
                onClick={layoutController?.toggleFocusMode}
              >
                {layoutController.isFocusMode ? (
                  <IconCollapse size={16} />
                ) : (
                  <IconExpand size={16} />
                )}
              </IconButton>
            </GooeyTooltip>
          )}
          {/* Close / minimize button */}
          {layoutController?.showCloseButton && (
            <GooeyTooltip text="Close">
              <IconButton
                aria-label="Close"
                variant="text"
                className={clsx("gp-8 cr-pointer flex-1")}
                onClick={layoutController?.toggleOpenClose}
              >
                <IconChevronDown size={16} />
              </IconButton>
            </GooeyTooltip>
          )}
          {/* Share conversation button - only show in gooey app site mode */}
          {config?.enableShareConversation &&
            !isEmpty &&
            layoutController?.isGooeyChatApp && (
              <ShareButton
                currentConversation={currentConversation || null}
                messages={messages}
                config={config}
                disabled={isSending || isReceiving || false}
              />
            )}

          {layoutController?.isInline && (
            <GooeyTooltip text="New Chat" disabled={isEmpty}>
              <IconButton
                aria-label="New Chat"
                disabled={isEmpty}
                variant="text"
                className={clsx("gp-8 cr-pointer flex-1")}
                onClick={handleNewConversation}
              >
                <IconPencilEdit size={22} />
              </IconButton>
            </GooeyTooltip>
          )}

          {!!onClose && (
            <IconButton
              aria-label="Close"
              variant="text"
              className={clsx("gp-8 cr-pointer flex-1")}
              onClick={onClose}
            >
              <IconClose size={22} />
            </IconButton>
          )}
        </div>
      </div>
    </div>
  );
};

export default Header;
